// Build digest - shared between the n8n Code node and the local preview.
// In n8n: jobs = $('Get jobs').all().map(i=>i.json); cfg from $('Get config'); rows = $input.all()
function buildDigest({ jobs, rows, cfg, now }) {
  now = now || new Date();
  const agency = cfg.agency_name || 'Your agency';
  const windowHours = Number(cfg.digest_window_hours) || 24;
  const atsLabel = cfg.ats_label || 'ATS';
  const primary = cfg.brand_primary || '#0ea672';
  const ink = cfg.brand_ink || '#111827';

  const c = {
    ink, primary,
    muted: '#6b7280', faint: '#9ca3af', line: '#e5e7eb', bg: '#f3f4f6', card: '#ffffff',
    warnBg: '#fff7ed', warnFg: '#9a3412', warnLine: '#fed7aa',
  };
  const band = {
    A: { bg: '#d1fae5', fg: '#065f46', label: 'A' },
    B: { bg: '#fef3c7', fg: '#92400e', label: 'B' },
    C: { bg: '#e5e7eb', fg: '#374151', label: 'C' },
  };

  const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const titleFor = {};
  for (const j of jobs) titleFor[String(j.job_ref || '').trim()] = j.title;

  const since = new Date(now.getTime() - windowHours * 3600 * 1000);
  const fmtDate = now.toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' });

  const recent = rows.filter(r => {
    const t = new Date(r.received_at);
    return !isNaN(t) && t >= since && t <= now;
  });
  const bandOf = r => (band[String(r.band || '').toUpperCase()] ? String(r.band).toUpperCase() : 'C');
  const isWaiting = r => !r.ack_status || r.ack_status === 'expired';
  const flagsOf = r => String(r.flags || '').split(/[;,|]\s*/).map(s => s.trim()).filter(f => f && !/^none$/i.test(f));

  const byJob = {};
  for (const r of recent) (byJob[String(r.job_ref || 'unknown').trim()] ||= []).push(r);
  const count = { A: 0, B: 0, C: 0 };
  for (const r of recent) count[bandOf(r)]++;
  const waiting = recent.filter(isWaiting);
  const sortedRefs = Object.keys(byJob).sort((a, b) => {
    const wa = byJob[a].filter(isWaiting).length, wb = byJob[b].filter(isWaiting).length;
    return wb - wa || a.localeCompare(b);
  });

  const status = r => {
    if (r.ack_status === 'sent') return { text: 'Acknowledged', fg: '#065f46', waiting: false };
    if (r.ack_status === 'held') return { text: 'On hold', fg: c.muted, waiting: false };
    return { text: 'Awaiting your decision', fg: c.warnFg, waiting: true };
  };
  const firstSentence = s => { const m = String(s || '').match(/^.*?[.!?](\s|$)/); return (m ? m[0] : String(s || '')).trim(); };

  // ---------- plain text ----------
  const text = [`${agency} - ${fmtDate}`, ''];
  if (!recent.length) text.push(`No new applications in the last ${windowHours} hours.`);
  else {
    text.push(`${recent.length} new: ${count.A} A, ${count.B} B, ${count.C} C.${waiting.length ? ` ${waiting.length} awaiting your decision.` : ''}`, '');
    for (const ref of sortedRefs) {
      const list = byJob[ref].sort((a, b) => Number(b.fit_score) - Number(a.fit_score));
      text.push(`${ref}${titleFor[ref] ? ' - ' + titleFor[ref] : ''} (${list.length})`);
      for (const r of list.slice(0, 5)) {
        text.push(`  ${r.fit_score}/10 ${bandOf(r)}  ${r.full_name}${r.current_title ? ' - ' + r.current_title : ''}${r.current_employer ? ' at ' + r.current_employer : ''} [${status(r).text}]`);
        const why = firstSentence(r.rationale); if (why) text.push(`    ${why}`);
        const fl = flagsOf(r); if (fl.length) text.push(`    Flags: ${fl.join('; ')}`);
        if (r.zoho_candidate_url) text.push(`    ${r.zoho_candidate_url}`);
      }
      if (list.length > 5) text.push(`  and ${list.length - 5} more in ${atsLabel}`);
      text.push('');
    }
  }

  // ---------- html ----------
  const font = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
  const pill = b => `<span style="display:inline-block;padding:3px 9px;border-radius:999px;background:${band[b].bg};color:${band[b].fg};font:600 11px/1 ${font};letter-spacing:.06em;text-transform:uppercase;">Band ${b}</span>`;
  const score = (n, b) => `<td width="44" valign="top" style="padding:0 12px 0 0;"><div style="width:44px;height:44px;border-radius:10px;background:${band[b].bg};color:${band[b].fg};font:700 18px/44px ${font};text-align:center;">${esc(n)}</div></td>`;

  const candidate = (r, last) => {
    const b = bandOf(r), st = status(r), why = firstSentence(r.rationale), fl = flagsOf(r);
    const role = [r.current_title, r.current_employer].filter(Boolean).join(' at ');
    const cta = r.zoho_candidate_url
      ? (st.waiting
        ? `<a href="${esc(r.zoho_candidate_url)}" style="display:inline-block;padding:10px 16px;border-radius:8px;background:${c.ink};color:#ffffff;font:600 13px/1 ${font};text-decoration:none;white-space:nowrap;">Review in ${esc(atsLabel)} &rarr;</a>`
        : `<a href="${esc(r.zoho_candidate_url)}" style="color:${c.primary};font:600 13px/1 ${font};text-decoration:none;">Open in ${esc(atsLabel)} &rarr;</a>`)
      : '';
    return `
      <tr><td style="padding:16px 0 ${last ? '4px' : '16px'};${last ? '' : `border-bottom:1px solid ${c.line};`}">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
          ${score(r.fit_score, b)}
          <td valign="top">
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
              <tr>
                <td style="font:600 16px/1.3 ${font};color:${c.ink};">${esc(r.full_name)}</td>
                <td align="right" valign="top" style="white-space:nowrap;padding-left:8px;">${pill(b)}</td>
              </tr>
              ${role ? `<tr><td colspan="2" style="padding-top:2px;font:13px/1.4 ${font};color:${c.muted};">${esc(role)}</td></tr>` : ''}
              ${why ? `<tr><td colspan="2" style="padding-top:8px;font:14px/1.5 ${font};color:${c.ink};">${esc(why)}</td></tr>` : ''}
              ${fl.length ? `<tr><td colspan="2" style="padding-top:8px;"><table role="presentation" cellpadding="0" cellspacing="0"><tr><td style="padding:6px 10px;border-radius:6px;background:${c.warnBg};border:1px solid ${c.warnLine};font:13px/1.4 ${font};color:${c.warnFg};">${fl.map(esc).join(' &nbsp;&middot;&nbsp; ')}</td></tr></table></td></tr>` : ''}
              <tr><td colspan="2" style="padding-top:10px;font:600 13px/1.3 ${font};color:${st.fg};">${st.text}</td></tr>
              ${cta ? `<tr><td colspan="2" align="right" style="padding-top:10px;white-space:nowrap;">${cta}</td></tr>` : ''}
            </table>
          </td>
        </tr></table>
      </td></tr>`;
  };

  let sections = '';
  if (!recent.length) {
    sections = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${c.card};border:1px solid ${c.line};border-radius:12px;"><tr><td style="padding:28px 24px;text-align:center;font:15px/1.5 ${font};color:${c.muted};">No new applications in the last ${windowHours} hours.</td></tr></table>`;
  } else {
    for (const ref of sortedRefs) {
      const list = byJob[ref].sort((a, b) => Number(b.fit_score) - Number(a.fit_score));
      const w = list.filter(isWaiting).length;
      const shown = list.slice(0, 5);
      sections += `
      <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${c.card};border:1px solid ${c.line};border-radius:12px;margin:0 0 16px;">
        <tr><td style="padding:18px 20px 4px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
            <td>
              <div style="font:600 11px/1 ${font};letter-spacing:.08em;text-transform:uppercase;color:${c.faint};">${esc(ref)}</div>
              <div style="font:700 18px/1.3 ${font};color:${c.ink};margin-top:4px;">${esc(titleFor[ref] || 'Role')}</div>
            </td>
            <td align="right" valign="top" style="white-space:nowrap;font:13px/1.4 ${font};color:${c.muted};">${list.length} new${w ? `<br><span style="color:${c.warnFg};font-weight:600;">${w} awaiting you</span>` : ''}</td>
          </tr></table>
        </td></tr>
        <tr><td style="padding:0 20px 12px;">
          <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
            ${shown.map((r, i) => candidate(r, i === shown.length - 1)).join('')}
            ${list.length > 5 ? `<tr><td style="padding:8px 0 4px;font:13px/1.4 ${font};color:${c.muted};">and ${list.length - 5} more in ${esc(atsLabel)}</td></tr>` : ''}
          </table>
        </td></tr>
      </table>`;
    }
  }

  const stat = (n, label, fg) => `<td align="center" style="padding:14px 4px;"><div style="font:700 26px/1 ${font};color:${fg || c.ink};">${n}</div><div style="margin-top:6px;font:12px/1 ${font};color:${c.muted};">${label}</div></td>`;
  const summary = `
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${c.card};border:1px solid ${c.line};border-radius:12px;">
      <tr>
        ${stat(recent.length, 'new')}
        ${stat(count.A, 'A-band', band.A.fg)}
        ${stat(count.B, 'B-band', band.B.fg)}
        ${stat(count.C, 'C-band', band.C.fg)}
        ${stat(waiting.length, 'awaiting you', waiting.length ? c.warnFg : c.ink)}
      </tr>
    </table>`;

  const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(agency)} digest</title></head>
<body style="margin:0;padding:0;background:${c.bg};">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:${c.bg};">
<tr><td align="center" style="padding:0 0 32px;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:600px;">
  <tr><td style="padding:0;"><div style="height:4px;background:${c.primary};border-radius:0 0 2px 2px;"></div></td></tr>
  <tr><td style="padding:22px 20px 16px;">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>
      <td style="font:700 15px/1 ${font};color:${c.ink};letter-spacing:-.01em;">${esc(agency)}</td>
      <td align="right" style="font:13px/1 ${font};color:${c.muted};">${esc(fmtDate)}</td>
    </tr></table>
    <div style="margin-top:18px;font:700 24px/1.2 ${font};color:${c.ink};letter-spacing:-.02em;">Morning digest</div>
    <div style="margin-top:6px;font:14px/1.5 ${font};color:${c.muted};">${recent.length ? `${recent.length} new application${recent.length === 1 ? '' : 's'} screened in the last ${windowHours} hours.${waiting.length ? ` <span style="color:${c.warnFg};font-weight:600;">${waiting.length} waiting on you.</span>` : ''}` : `Nothing new in the last ${windowHours} hours.`}</div>
  </td></tr>
  <tr><td style="padding:0 20px 16px;">${summary}</td></tr>
  <tr><td style="padding:0 20px;">${sections}</td></tr>
  <tr><td style="padding:8px 20px 0;font:12px/1.6 ${font};color:${c.faint};">Applications are screened and filed in ${esc(atsLabel)} automatically. Nothing is sent to a candidate without your approval.<br>Run for ${esc(agency)} by OpsAutomated.</td></tr>
</table>
</td></tr></table></body></html>`;

  const subject = recent.length
    ? `${fmtDate}: ${recent.length} new${count.A ? `, ${count.A} A-band` : ''}${waiting.length ? `, ${waiting.length} awaiting you` : ''}`
    : `${fmtDate}: no new applications`;

  return { subject, body: text.join('\n'), html };
}

const cfg = $('Config').first().json;
const jobs = $('Get jobs').all().map(i => i.json);
const rows = $input.all().map(i => i.json);
return [{ json: buildDigest({ jobs, rows, cfg }) }];
